INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-02','HSK1-02','HSK 1 · Đề 02','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 02 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-02-q01','seed-hsk1-02',1,'single_choice','Pinyin phù hợp với “狗” là phương án nào?','Pinyin của “狗” là “gǒu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chó”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q02','seed-hsk1-02',2,'single_choice','Chọn từ Hán ngữ có nghĩa “xin chào”.','Từ phù hợp là “你好”, đọc là nǐ hǎo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q03','seed-hsk1-02',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “学生 — xuésheng”, nghĩa là “học sinh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q04','seed-hsk1-02',4,'single_choice','Từ “今天” gần nghĩa nhất với phương án nào?','“今天” (jīntiān) có nghĩa là “hôm nay”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q05','seed-hsk1-02',5,'single_choice','Pinyin phù hợp với “中国” là phương án nào?','Pinyin của “中国” là “Zhōngguó”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “Trung Quốc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q06','seed-hsk1-02',6,'single_choice','Chọn từ Hán ngữ có nghĩa “uống”.','Từ phù hợp là “喝”, đọc là hē. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q07','seed-hsk1-02',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “茶 — chá”, nghĩa là “trà”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q08','seed-hsk1-02',8,'single_choice','Từ “大” gần nghĩa nhất với phương án nào?','“大” (dà) có nghĩa là “lớn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q09','seed-hsk1-02',9,'single_choice','Pinyin phù hợp với “谢谢” là phương án nào?','Pinyin của “谢谢” là “xièxie”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cảm ơn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-02-q10','seed-hsk1-02',10,'single_choice','Chọn từ Hán ngữ có nghĩa “giáo viên”.','Từ phù hợp là “老师”, đọc là lǎoshī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
