INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-03','HSK1-03','HSK 1 · Đề 03','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-03-q01','seed-hsk1-03',1,'single_choice','Pinyin phù hợp với “老师” là phương án nào?','Pinyin của “老师” là “lǎoshī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giáo viên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q02','seed-hsk1-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “ngày mai”.','Từ phù hợp là “明天”, đọc là míngtiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q03','seed-hsk1-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “喜欢 — xǐhuan”, nghĩa là “thích”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q04','seed-hsk1-03',4,'single_choice','Từ “吃” gần nghĩa nhất với phương án nào?','“吃” (chī) có nghĩa là “ăn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q05','seed-hsk1-03',5,'single_choice','Pinyin phù hợp với “猫” là phương án nào?','Pinyin của “猫” là “māo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mèo”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q06','seed-hsk1-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “nhỏ”.','Từ phù hợp là “小”, đọc là xiǎo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q07','seed-hsk1-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “再见 — zàijiàn”, nghĩa là “tạm biệt”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q08','seed-hsk1-03',8,'single_choice','Từ “朋友” gần nghĩa nhất với phương án nào?','“朋友” (péngyou) có nghĩa là “bạn bè”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q09','seed-hsk1-03',9,'single_choice','Pinyin phù hợp với “学校” là phương án nào?','Pinyin của “学校” là “xuéxiào”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trường học”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q10','seed-hsk1-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “học tập”.','Từ phù hợp là “学习”, đọc là xuéxí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q11','seed-hsk1-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “水 — shuǐ”, nghĩa là “nước”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q12','seed-hsk1-03',12,'single_choice','Từ “狗” gần nghĩa nhất với phương án nào?','“狗” (gǒu) có nghĩa là “chó”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q13','seed-hsk1-03',13,'single_choice','Pinyin phù hợp với “你好” là phương án nào?','Pinyin của “你好” là “nǐ hǎo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xin chào”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q14','seed-hsk1-03',14,'single_choice','Chọn từ Hán ngữ có nghĩa “học sinh”.','Từ phù hợp là “学生”, đọc là xuésheng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-03-q15','seed-hsk1-03',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “今天 — jīntiān”, nghĩa là “hôm nay”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
