INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-04','HSK1-04','HSK 1 · Đề 04','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 04 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-04-q01','seed-hsk1-04',1,'single_choice','Pinyin phù hợp với “学习” là phương án nào?','Pinyin của “学习” là “xuéxí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “học tập”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q02','seed-hsk1-04',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nước”.','Từ phù hợp là “水”, đọc là shuǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q03','seed-hsk1-04',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “狗 — gǒu”, nghĩa là “chó”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q04','seed-hsk1-04',4,'single_choice','Từ “你好” gần nghĩa nhất với phương án nào?','“你好” (nǐ hǎo) có nghĩa là “xin chào”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q05','seed-hsk1-04',5,'single_choice','Pinyin phù hợp với “学生” là phương án nào?','Pinyin của “学生” là “xuésheng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “học sinh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q06','seed-hsk1-04',6,'single_choice','Chọn từ Hán ngữ có nghĩa “hôm nay”.','Từ phù hợp là “今天”, đọc là jīntiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q07','seed-hsk1-04',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “中国 — Zhōngguó”, nghĩa là “Trung Quốc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q08','seed-hsk1-04',8,'single_choice','Từ “喝” gần nghĩa nhất với phương án nào?','“喝” (hē) có nghĩa là “uống”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q09','seed-hsk1-04',9,'single_choice','Pinyin phù hợp với “茶” là phương án nào?','Pinyin của “茶” là “chá”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trà”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q10','seed-hsk1-04',10,'single_choice','Chọn từ Hán ngữ có nghĩa “lớn”.','Từ phù hợp là “大”, đọc là dà. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q11','seed-hsk1-04',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “谢谢 — xièxie”, nghĩa là “cảm ơn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q12','seed-hsk1-04',12,'single_choice','Từ “老师” gần nghĩa nhất với phương án nào?','“老师” (lǎoshī) có nghĩa là “giáo viên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-04-q13','seed-hsk1-04',13,'single_choice','Pinyin phù hợp với “明天” là phương án nào?','Pinyin của “明天” là “míngtiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngày mai”.',NULL,NULL,0,1,'',datetime('now')),
