INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-05','HSK1-05','HSK 1 · Đề 05','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 05 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-05-q01','seed-hsk1-05',1,'single_choice','Pinyin phù hợp với “大” là phương án nào?','Pinyin của “大” là “dà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lớn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q02','seed-hsk1-05',2,'single_choice','Chọn từ Hán ngữ có nghĩa “cảm ơn”.','Từ phù hợp là “谢谢”, đọc là xièxie. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q03','seed-hsk1-05',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “老师 — lǎoshī”, nghĩa là “giáo viên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q04','seed-hsk1-05',4,'single_choice','Từ “明天” gần nghĩa nhất với phương án nào?','“明天” (míngtiān) có nghĩa là “ngày mai”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q05','seed-hsk1-05',5,'single_choice','Pinyin phù hợp với “喜欢” là phương án nào?','Pinyin của “喜欢” là “xǐhuan”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thích”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q06','seed-hsk1-05',6,'single_choice','Chọn từ Hán ngữ có nghĩa “ăn”.','Từ phù hợp là “吃”, đọc là chī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q07','seed-hsk1-05',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “猫 — māo”, nghĩa là “mèo”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q08','seed-hsk1-05',8,'single_choice','Từ “小” gần nghĩa nhất với phương án nào?','“小” (xiǎo) có nghĩa là “nhỏ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q09','seed-hsk1-05',9,'single_choice','Pinyin phù hợp với “再见” là phương án nào?','Pinyin của “再见” là “zàijiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tạm biệt”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q10','seed-hsk1-05',10,'single_choice','Chọn từ Hán ngữ có nghĩa “bạn bè”.','Từ phù hợp là “朋友”, đọc là péngyou. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q11','seed-hsk1-05',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “学校 — xuéxiào”, nghĩa là “trường học”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-05-q12','seed-hsk1-05',12,'single_choice','Từ “学习” gần nghĩa nhất với phương án nào?','“学习” (xuéxí) có nghĩa là “học tập”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
