('seed-hsk1-06-q38','seed-hsk1-06',38,'single_choice','Chọn từ Hán ngữ có nghĩa “mèo”.','Từ phù hợp là “猫”, đọc là māo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q39','seed-hsk1-06',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “小 — xiǎo”, nghĩa là “nhỏ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q40','seed-hsk1-06',40,'single_choice','Từ “再见” gần nghĩa nhất với phương án nào?','“再见” (zàijiàn) có nghĩa là “tạm biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q41','seed-hsk1-06',41,'single_choice','Pinyin phù hợp với “朋友” là phương án nào?','Pinyin của “朋友” là “péngyou”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bạn bè”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q42','seed-hsk1-06',42,'single_choice','Chọn từ Hán ngữ có nghĩa “trường học”.','Từ phù hợp là “学校”, đọc là xuéxiào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q43','seed-hsk1-06',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “学习 — xuéxí”, nghĩa là “học tập”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q44','seed-hsk1-06',44,'single_choice','Từ “水” gần nghĩa nhất với phương án nào?','“水” (shuǐ) có nghĩa là “nước”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q45','seed-hsk1-06',45,'single_choice','Pinyin phù hợp với “狗” là phương án nào?','Pinyin của “狗” là “gǒu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chó”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-06-q46','seed-hsk1-06',46,'single_choice','Chọn từ Hán ngữ có nghĩa “xin chào”.','Từ phù hợp là “你好”, đọc là nǐ hǎo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
