('seed-hsk1-07-q45','seed-hsk1-07',45,'single_choice','Pinyin phù hợp với “老师” là phương án nào?','Pinyin của “老师” là “lǎoshī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giáo viên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-07-q46','seed-hsk1-07',46,'single_choice','Chọn từ Hán ngữ có nghĩa “ngày mai”.','Từ phù hợp là “明天”, đọc là míngtiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-07-q47','seed-hsk1-07',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “喜欢 — xǐhuan”, nghĩa là “thích”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-07-q48','seed-hsk1-07',48,'single_choice','Từ “吃” gần nghĩa nhất với phương án nào?','“吃” (chī) có nghĩa là “ăn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-07-q49','seed-hsk1-07',49,'single_choice','Pinyin phù hợp với “猫” là phương án nào?','Pinyin của “猫” là “māo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mèo”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-07-q50','seed-hsk1-07',50,'single_choice','Chọn từ Hán ngữ có nghĩa “nhỏ”.','Từ phù hợp là “小”, đọc là xiǎo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
