INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-10','HSK1-10','HSK 1 · Đề 10','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 10 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-10-q01','seed-hsk1-10',1,'single_choice','Pinyin phù hợp với “吃” là phương án nào?','Pinyin của “吃” là “chī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ăn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q02','seed-hsk1-10',2,'single_choice','Chọn từ Hán ngữ có nghĩa “mèo”.','Từ phù hợp là “猫”, đọc là māo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q03','seed-hsk1-10',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “小 — xiǎo”, nghĩa là “nhỏ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q04','seed-hsk1-10',4,'single_choice','Từ “再见” gần nghĩa nhất với phương án nào?','“再见” (zàijiàn) có nghĩa là “tạm biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q05','seed-hsk1-10',5,'single_choice','Pinyin phù hợp với “朋友” là phương án nào?','Pinyin của “朋友” là “péngyou”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bạn bè”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q06','seed-hsk1-10',6,'single_choice','Chọn từ Hán ngữ có nghĩa “trường học”.','Từ phù hợp là “学校”, đọc là xuéxiào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q07','seed-hsk1-10',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “学习 — xuéxí”, nghĩa là “học tập”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q08','seed-hsk1-10',8,'single_choice','Từ “水” gần nghĩa nhất với phương án nào?','“水” (shuǐ) có nghĩa là “nước”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q09','seed-hsk1-10',9,'single_choice','Pinyin phù hợp với “狗” là phương án nào?','Pinyin của “狗” là “gǒu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chó”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-10-q10','seed-hsk1-10',10,'single_choice','Chọn từ Hán ngữ có nghĩa “xin chào”.','Từ phù hợp là “你好”, đọc là nǐ hǎo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
