INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-12','HSK1-12','HSK 1 · Đề 12','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 12 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-12-q01','seed-hsk1-12',1,'single_choice','Pinyin phù hợp với “明天” là phương án nào?','Pinyin của “明天” là “míngtiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngày mai”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q02','seed-hsk1-12',2,'single_choice','Chọn từ Hán ngữ có nghĩa “thích”.','Từ phù hợp là “喜欢”, đọc là xǐhuan. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q03','seed-hsk1-12',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “吃 — chī”, nghĩa là “ăn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q04','seed-hsk1-12',4,'single_choice','Từ “猫” gần nghĩa nhất với phương án nào?','“猫” (māo) có nghĩa là “mèo”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q05','seed-hsk1-12',5,'single_choice','Pinyin phù hợp với “小” là phương án nào?','Pinyin của “小” là “xiǎo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhỏ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q06','seed-hsk1-12',6,'single_choice','Chọn từ Hán ngữ có nghĩa “tạm biệt”.','Từ phù hợp là “再见”, đọc là zàijiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q07','seed-hsk1-12',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “朋友 — péngyou”, nghĩa là “bạn bè”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q08','seed-hsk1-12',8,'single_choice','Từ “学校” gần nghĩa nhất với phương án nào?','“学校” (xuéxiào) có nghĩa là “trường học”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q09','seed-hsk1-12',9,'single_choice','Pinyin phù hợp với “学习” là phương án nào?','Pinyin của “学习” là “xuéxí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “học tập”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q10','seed-hsk1-12',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nước”.','Từ phù hợp là “水”, đọc là shuǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
