('seed-hsk1-12-q12','seed-hsk1-12',12,'single_choice','Từ “你好” gần nghĩa nhất với phương án nào?','“你好” (nǐ hǎo) có nghĩa là “xin chào”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
