('seed-hsk1-12-q23','seed-hsk1-12',23,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “吃 — chī”, nghĩa là “ăn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-12-q24','seed-hsk1-12',24,'single_choice','Từ “猫” gần nghĩa nhất với phương án nào?','“猫” (māo) có nghĩa là “mèo”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
