INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-13','HSK1-13','HSK 1 · Đề 13','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 13 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-13-q01','seed-hsk1-13',1,'single_choice','Pinyin phù hợp với “水” là phương án nào?','Pinyin của “水” là “shuǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nước”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q02','seed-hsk1-13',2,'single_choice','Chọn từ Hán ngữ có nghĩa “chó”.','Từ phù hợp là “狗”, đọc là gǒu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q03','seed-hsk1-13',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “你好 — nǐ hǎo”, nghĩa là “xin chào”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q04','seed-hsk1-13',4,'single_choice','Từ “学生” gần nghĩa nhất với phương án nào?','“学生” (xuésheng) có nghĩa là “học sinh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q05','seed-hsk1-13',5,'single_choice','Pinyin phù hợp với “今天” là phương án nào?','Pinyin của “今天” là “jīntiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hôm nay”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q06','seed-hsk1-13',6,'single_choice','Chọn từ Hán ngữ có nghĩa “Trung Quốc”.','Từ phù hợp là “中国”, đọc là Zhōngguó. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q07','seed-hsk1-13',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “喝 — hē”, nghĩa là “uống”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q08','seed-hsk1-13',8,'single_choice','Từ “茶” gần nghĩa nhất với phương án nào?','“茶” (chá) có nghĩa là “trà”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q09','seed-hsk1-13',9,'single_choice','Pinyin phù hợp với “大” là phương án nào?','Pinyin của “大” là “dà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lớn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q10','seed-hsk1-13',10,'single_choice','Chọn từ Hán ngữ có nghĩa “cảm ơn”.','Từ phù hợp là “谢谢”, đọc là xièxie. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q11','seed-hsk1-13',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “老师 — lǎoshī”, nghĩa là “giáo viên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
