('seed-hsk1-13-q31','seed-hsk1-13',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “老师 — lǎoshī”, nghĩa là “giáo viên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q32','seed-hsk1-13',32,'single_choice','Từ “明天” gần nghĩa nhất với phương án nào?','“明天” (míngtiān) có nghĩa là “ngày mai”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q33','seed-hsk1-13',33,'single_choice','Pinyin phù hợp với “喜欢” là phương án nào?','Pinyin của “喜欢” là “xǐhuan”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thích”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-13-q34','seed-hsk1-13',34,'single_choice','Chọn từ Hán ngữ có nghĩa “ăn”.','Từ phù hợp là “吃”, đọc là chī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
