INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk1-14','HSK1-14','HSK 1 · Đề 14','hsk','HSK 1',55,'published',1,'Đề luyện HSK 1 số 14 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk1-14-q01','seed-hsk1-14',1,'single_choice','Pinyin phù hợp với “谢谢” là phương án nào?','Pinyin của “谢谢” là “xièxie”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cảm ơn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q02','seed-hsk1-14',2,'single_choice','Chọn từ Hán ngữ có nghĩa “giáo viên”.','Từ phù hợp là “老师”, đọc là lǎoshī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q03','seed-hsk1-14',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “明天 — míngtiān”, nghĩa là “ngày mai”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q04','seed-hsk1-14',4,'single_choice','Từ “喜欢” gần nghĩa nhất với phương án nào?','“喜欢” (xǐhuan) có nghĩa là “thích”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q05','seed-hsk1-14',5,'single_choice','Pinyin phù hợp với “吃” là phương án nào?','Pinyin của “吃” là “chī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ăn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q06','seed-hsk1-14',6,'single_choice','Chọn từ Hán ngữ có nghĩa “mèo”.','Từ phù hợp là “猫”, đọc là māo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q07','seed-hsk1-14',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “小 — xiǎo”, nghĩa là “nhỏ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q08','seed-hsk1-14',8,'single_choice','Từ “再见” gần nghĩa nhất với phương án nào?','“再见” (zàijiàn) có nghĩa là “tạm biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q09','seed-hsk1-14',9,'single_choice','Pinyin phù hợp với “朋友” là phương án nào?','Pinyin của “朋友” là “péngyou”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bạn bè”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q10','seed-hsk1-14',10,'single_choice','Chọn từ Hán ngữ có nghĩa “trường học”.','Từ phù hợp là “学校”, đọc là xuéxiào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
