('seed-hsk1-14-q12','seed-hsk1-14',12,'single_choice','Từ “水” gần nghĩa nhất với phương án nào?','“水” (shuǐ) có nghĩa là “nước”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q13','seed-hsk1-14',13,'single_choice','Pinyin phù hợp với “狗” là phương án nào?','Pinyin của “狗” là “gǒu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chó”.',NULL,NULL,0,1,'',datetime('now')),
