('seed-hsk1-14-q38','seed-hsk1-14',38,'single_choice','Chọn từ Hán ngữ có nghĩa “uống”.','Từ phù hợp là “喝”, đọc là hē. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q39','seed-hsk1-14',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “茶 — chá”, nghĩa là “trà”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q40','seed-hsk1-14',40,'single_choice','Từ “大” gần nghĩa nhất với phương án nào?','“大” (dà) có nghĩa là “lớn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q41','seed-hsk1-14',41,'single_choice','Pinyin phù hợp với “谢谢” là phương án nào?','Pinyin của “谢谢” là “xièxie”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cảm ơn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q42','seed-hsk1-14',42,'single_choice','Chọn từ Hán ngữ có nghĩa “giáo viên”.','Từ phù hợp là “老师”, đọc là lǎoshī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q43','seed-hsk1-14',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “明天 — míngtiān”, nghĩa là “ngày mai”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q44','seed-hsk1-14',44,'single_choice','Từ “喜欢” gần nghĩa nhất với phương án nào?','“喜欢” (xǐhuan) có nghĩa là “thích”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q45','seed-hsk1-14',45,'single_choice','Pinyin phù hợp với “吃” là phương án nào?','Pinyin của “吃” là “chī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ăn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q46','seed-hsk1-14',46,'single_choice','Chọn từ Hán ngữ có nghĩa “mèo”.','Từ phù hợp là “猫”, đọc là māo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q47','seed-hsk1-14',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “小 — xiǎo”, nghĩa là “nhỏ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q48','seed-hsk1-14',48,'single_choice','Từ “再见” gần nghĩa nhất với phương án nào?','“再见” (zàijiàn) có nghĩa là “tạm biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q49','seed-hsk1-14',49,'single_choice','Pinyin phù hợp với “朋友” là phương án nào?','Pinyin của “朋友” là “péngyou”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bạn bè”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-14-q50','seed-hsk1-14',50,'single_choice','Chọn từ Hán ngữ có nghĩa “trường học”.','Từ phù hợp là “学校”, đọc là xuéxiào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
