('seed-hsk1-15-q45','seed-hsk1-15',45,'single_choice','Pinyin phù hợp với “你好” là phương án nào?','Pinyin của “你好” là “nǐ hǎo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xin chào”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-15-q46','seed-hsk1-15',46,'single_choice','Chọn từ Hán ngữ có nghĩa “học sinh”.','Từ phù hợp là “学生”, đọc là xuésheng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-15-q47','seed-hsk1-15',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “今天 — jīntiān”, nghĩa là “hôm nay”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-15-q48','seed-hsk1-15',48,'single_choice','Từ “中国” gần nghĩa nhất với phương án nào?','“中国” (Zhōngguó) có nghĩa là “Trung Quốc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-15-q49','seed-hsk1-15',49,'single_choice','Pinyin phù hợp với “喝” là phương án nào?','Pinyin của “喝” là “hē”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “uống”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-15-q50','seed-hsk1-15',50,'single_choice','Chọn từ Hán ngữ có nghĩa “trà”.','Từ phù hợp là “茶”, đọc là chá. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
