('seed-hsk1-20-q24','seed-hsk1-20',24,'single_choice','Từ “喝” gần nghĩa nhất với phương án nào?','“喝” (hē) có nghĩa là “uống”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 1.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk1-20-q25','seed-hsk1-20',25,'single_choice','Pinyin phù hợp với “茶” là phương án nào?','Pinyin của “茶” là “chá”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trà”.',NULL,NULL,0,1,'',datetime('now')),
